static int sucs_ucd_name_bsearch(sucs_char_t cp) {
    int lo = 0;
    int hi = SUCS_UCD_NAME_COUNT - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        uint32_t mid_cp = sucs_ucd_name_index[mid].cp;
        if (cp < mid_cp) {
            hi = mid - 1;
        } else if (cp > mid_cp) {
            lo = mid + 1;
        } else {
            return mid;
        }
    }
    return -1;
}

const char* sucs_ucd_get_name(sucs_char_t cp) {
    int idx = sucs_ucd_name_bsearch(cp);
    if (idx < 0) return (const char*)0;
    return &sucs_ucd_name_pool[sucs_ucd_name_index[idx].name_offset];
}

uint16_t sucs_ucd_name_length(sucs_char_t cp) {
    int idx = sucs_ucd_name_bsearch(cp);
    if (idx < 0) return 0;
    return sucs_ucd_name_index[idx].name_length;
}

uint16_t sucs_ucd_get_name_copy(sucs_char_t cp, char* out_buf, uint16_t buf_size) {
    int idx = sucs_ucd_name_bsearch(cp);
    if (idx < 0) return 0;
    uint16_t len = sucs_ucd_name_index[idx].name_length;
    if (len >= buf_size) return 0;
    const char* src = &sucs_ucd_name_pool[sucs_ucd_name_index[idx].name_offset];
    for (uint16_t i = 0; i < len; i++) {
        out_buf[i] = src[i];
    }
    out_buf[len] = '\0';
    return len;
}
